      SUBROUTINE AGSCC     CALCULATES PARTIALS FOR THE AGS MACHINE CONSTRAINTC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'CONSTS.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'CC     LOCAL VARIABLESC      INTEGER         J, K, L1, N      LOGICAL         LOGIC      REAL            RCT, RCTVC--------------------------------------------------------------------C      J = - (JCON + 10)      K = KCONC      IF (RCP) GO TO 10      RCT = RC2(J,J) + RC2(K,K)      GO TO 50C   10 IF (R2P) GO TO 20      RCT = RC(J,J) + RC(K,K)      GO TO 50C   20 RCT = 0.0      DO 30 L1 = 1, 6      RCT = RCT + RC2(J,L1)*RC(L1,J) + RC2(K,L1)*RC(L1,K)   30 CONTINUEC   50 COC = RCT      IF (ABS(COC) .GT. 2.0) GO TO 100      COCO = ACOS(0.5*COC)/(2.0*PI)   60 IF (DE0 - COCO .LT. 0.5) GO TO 70      COCO = COCO + 1.0      GO TO 60   70 IF (DE0 - COCO .GT. -0.5) GO TO 80      COCO = COCO - 1.0      GO TO 70   80 COCO = 2.0*PI*COCO/UNITO(12)C  100 IF (NV3 .LT. 1) GO TO 250      A(1) = 2.0*COS(UNITO(12)*DE0) - COC      CALL CLI(LOGIC)      IF (LOGIC) GO TO 300C      CW = ( - 1.0/(2.0*UNITO(12)*SIN(UNITO(12)*DE0)*SD))**2      IF (NV1 .LT. 1) GO TO 250      DO 200 N = 1, NV1      RCTV = 0.0      IF (.NOT. (RVP(N) .OR. R2VP(N))) GO TO 200      IF (RCP) GO TO 110      RCTV = R2V(J,J,N) + R2V(K,K,N)      GO TO 150  110 IF (R2P) GO TO 120      RCTV = RCV(J,J,N) + RCV(K,K,N)      GO TO 150  120 IF (R2VP(N)) GO TO 130      DO 125 L1 = 1, 6      RCTV = RCTV + RC2(J,L1)*RCV(L1,J,N) + RC2(K,L1)*RCV(L1,K,N)  125 CONTINUE      GO TO 150  130 IF (RVP(N)) THEN        DO 135 L1 = 1, 6        RCTV = RCTV + R2V(J,L1,N)*RC(L1,J) + R2V(K,L1,N)*RC(L1,K)     1       + RC2(J,L1)*RCV(L1,J,N) + RC2(K,L1)*RCV(L1,K,N)  135   CONTINUE      ELSE        DO 140 L1 = 1, 6        RCTV = RCTV + R2V(J,L1,N)*RC(L1,J) + R2V(K,L1,N)*RC(L1,K)  140   CONTINUE      ENDIF  150 A(N+1) = RCTV  200 CONTINUE  250 CALL GATHERC  300 RETURN      END